from lc import L, w, gr, q

B2 = [
 L("Is Breakfast Really the Most Important Meal?", "早餐真的是最重要的一餐嗎？", [
   "Many of us grew up hearing that breakfast is the most important meal of the day. Interestingly, this idea was strongly promoted in the past by companies that sold breakfast cereals.",
   "Scientific research gives a more mixed picture. Some studies link eating breakfast with better concentration, especially in children at school. For healthy adults, however, skipping breakfast does not seem to be harmful for everyone, and some people simply feel better eating later.",
   "What probably matters more is what you eat. A breakfast with protein, whole grains and fruit keeps you full for longer than sugary cereal or pastries, which can make your energy rise quickly and then crash before lunch."],
  [w("promote","verb","/prəˈmoʊt/","推廣","to encourage people to like or buy something","promote a product","be promoted by… 被…推廣。"),
   w("cereal","noun","/ˈsɪr.i.əl/","穀片","a breakfast food made from grains, eaten with milk","a bowl of cereal","breakfast cereals 早餐穀片。"),
   w("mixed","adjective","/mɪkst/","好壞參半的","including both good and bad","mixed reviews","a mixed picture 好壞參半的情況。"),
   w("skip","verb","/skɪp/","略過","to not do something you usually do","skip a class","skipping breakfast 不吃早餐（動名詞）。"),
   w("harmful","adjective","/ˈhɑːrm.fəl/","有害的","causing damage","harmful chemicals","be harmful 有害。"),
   w("protein","noun","/ˈproʊ.tiːn/","蛋白質","a substance in food such as meat and eggs that the body needs","high in protein","protein 蛋白質（不可數）。"),
   w("crash","verb","/kræʃ/","驟降","to fall suddenly","Stock prices crashed.","rise quickly and then crash 快速上升後驟降。")],
  [gr("grow up + V-ing","從小就一直…。","Many of us grew up hearing that breakfast is the most important meal of the day."),
   gr("What 名詞子句當主詞","What probably matters more = 更重要的事。","What probably matters more is what you eat."),
   gr("keep + 受詞 + 形容詞","使…保持…。","keeps you full for longer than sugary cereal or pastries")],
  [q("Who strongly promoted the idea that breakfast is most important?","Companies that sold cereals","Doctors only","Schools"),
   q("What does research say about skipping breakfast for healthy adults?","It does not seem harmful for everyone","It is always dangerous","It makes everyone thinner"),
   q("Which breakfast keeps you full longer?","Protein, whole grains and fruit","Sugary pastries","Only coffee")]),
 L("Life on the International Space Station", "國際太空站上的生活", [
   "The International Space Station is a science laboratory that orbits about 400 kilometers above the Earth. It travels so fast that it circles the planet roughly every 90 minutes, so astronauts on board can see around 16 sunrises a day.",
   "The station was built in pieces from 1998 and has had people living on it continuously since 2000. It is a partnership between space agencies from the United States, Russia, Europe, Japan and Canada.",
   "Life in near-weightlessness is challenging. Astronauts must exercise for about two hours every day to stop their muscles and bones from getting weaker. Their experiments help scientists learn how the human body changes in space, which will be important for future trips to the Moon and Mars."],
  [w("laboratory","noun","/ˈlæb.rə.tɔːr.i/","實驗室","a room or building for scientific work","a science laboratory","常簡稱 lab。"),
   w("orbit","verb","/ˈɔːr.bɪt/","繞軌道運行","to move around a planet or star","The Moon orbits the Earth.","orbits 第三人稱單數。"),
   w("circle","verb","/ˈsɝː.kəl/","繞圈","to move around something","Birds circled above.","circles the planet 繞行地球。"),
   w("continuously","adverb","/kənˈtɪn.ju.əs.li/","連續不斷地","without stopping","work continuously","living on it continuously 一直有人住。"),
   w("partnership","noun","/ˈpɑːrt.nɚ.ʃɪp/","合作關係","working together with others","a business partnership","a partnership between… …之間的合作。"),
   w("weightlessness","noun","/ˈweɪt.ləs.nəs/","失重","the state of having no weight, as in space","Weightlessness affects bones.","near-weightlessness 近乎失重。"),
   w("muscle","noun","/ˈmʌs.əl/","肌肉","body tissue that helps you move","strong muscles","muscles and bones 肌肉和骨骼。")],
  [gr("so… that…","如此…以致於…。","It travels so fast that it circles the planet roughly every 90 minutes"),
   gr("現在完成式 has had… since","從…以來一直…。","has had people living on it continuously since 2000"),
   gr("stop A from V-ing","防止 A…。","to stop their muscles and bones from getting weaker")],
  [q("How often does the ISS circle the Earth?","About every 90 minutes","Once a day","Once a week"),
   q("Since when have people lived on the station continuously?","2000","1969","2015"),
   q("Why must astronauts exercise every day?","To keep muscles and bones strong","To stay warm","To make electricity")]),
 L("The Real Cost of Cheap Clothes", "便宜衣服的真正代價", [
   "Fast fashion brands can move a design from the catwalk to the shop in just a few weeks, and they sell clothes at very low prices. As a result, people around the world are buying more clothes than ever and wearing each item fewer times.",
   "This model has serious costs. Making textiles uses large amounts of water and chemicals, and many synthetic fabrics are made from oil. In some countries, garment workers earn very low wages and work in unsafe conditions.",
   "Much of the clothing we throw away ends up in landfills or is burned. To reduce the impact, experts suggest buying fewer but better items, repairing clothes, and choosing second-hand shops or clothing swaps."],
  [w("catwalk","noun","/ˈkæt.wɑːk/","伸展台","the stage where models show new clothes","models on the catwalk","from the catwalk to the shop 從伸展台到店裡。"),
   w("item","noun","/ˈaɪ.t̬əm/","物品、件","a single thing in a list or group","an item of clothing","each item 每一件。"),
   w("textile","noun","/ˈtek.staɪl/","紡織品","cloth or fabric","the textile industry","making textiles 製造紡織品。"),
   w("synthetic","adjective","/sɪnˈθet̬.ɪk/","合成的","made artificially, not natural","synthetic fabrics","synthetic fabrics 合成纖維。"),
   w("garment","noun","/ˈɡɑːr.mənt/","衣服","a piece of clothing","garment factories","garment workers 成衣工人。"),
   w("wage","noun","/weɪdʒ/","工資","money paid for work","low wages","very low wages 很低的工資。"),
   w("swap","noun","/swɑːp/","交換","an exchange of one thing for another","a clothing swap","clothing swaps 換衣活動。")],
  [gr("As a result","因此。","As a result, people around the world are buying more clothes than ever"),
   gr("be made from","由…製成（原料改變形態）。","many synthetic fabrics are made from oil"),
   gr("fewer but better","少而精。","buying fewer but better items")],
  [q("What does fast fashion do quickly?","Moves designs from catwalk to shop","Repairs old clothes","Pays high wages"),
   q("Which problem of textile production is mentioned?","Using lots of water and chemicals","Using too little oil","Making clothes too strong"),
   q("What do experts suggest?","Buying fewer but better items","Buying more cheap clothes","Throwing clothes away quickly")]),
 L("What Makes a Good Life?", "什麼造就美好人生？", [
   "Psychiatrist Robert Waldinger directs one of the longest studies of adult life ever done. Since 1938, the Harvard Study of Adult Development has followed the lives of hundreds of men, from Harvard students to boys from poor Boston neighborhoods.",
   "In his TED talk, Waldinger shares the clearest lesson from all that data. It is not wealth or fame that keeps people happy and healthy as they age, but good relationships. People who were more connected to family, friends and community lived longer and were happier, while loneliness turned out to be harmful.",
   "He adds that quality matters more than quantity. Living in the middle of constant conflict can be bad for health, while warm relationships seem to protect both our bodies and our brains."],
  [w("psychiatrist","noun","/saɪˈkaɪə.trɪst/","精神科醫師","a doctor who treats mental illness","see a psychiatrist","psychiatrist 精神科醫師。"),
   w("direct","verb","/daɪˈrekt/","主持、領導","to be in charge of something","direct a project","directs 第三人稱單數。"),
   w("wealth","noun","/welθ/","財富","a large amount of money","great wealth","wealth or fame 財富或名聲。"),
   w("fame","noun","/feɪm/","名聲","being known by many people","rise to fame","形容詞 famous。"),
   w("age","verb","/eɪdʒ/","變老","to become older","as we age","as they age 隨著年紀增長。"),
   w("loneliness","noun","/ˈloʊn.li.nəs/","寂寞","the feeling of being alone and unhappy","Loneliness is harmful.","lonely 的名詞。"),
   w("conflict","noun","/ˈkɑːn.flɪkt/","衝突","serious disagreement","family conflict","constant conflict 持續的衝突。")],
  [gr("It is not A… but B","強調句：不是 A 而是 B。","It is not wealth or fame that keeps people happy and healthy as they age, but good relationships."),
   gr("turn out to be","結果證明是…。","loneliness turned out to be harmful"),
   gr("quality matters more than quantity","質比量重要。","quality matters more than quantity")],
  [q("When did the Harvard study begin?","1938","1998","2010"),
   q("What is the clearest lesson of the study?","Good relationships keep us happy and healthy","Money makes us happy","Fame helps us live longer"),
   q("What does Waldinger say about relationships?","Quality matters more than quantity","More friends is always better","Conflict is healthy")]),
]

C1 = [
 L("Rethinking 'the Most Important Meal of the Day'", "重新思考「一天最重要的一餐」", [
   "Few nutritional maxims are repeated as confidently as the claim that breakfast is the most important meal of the day. Its pedigree, however, is partly commercial: in the early twentieth century, cereal manufacturers did a great deal to popularize the notion through advertising.",
   "The science that followed is more equivocal than the slogan. Observational studies long found that breakfast eaters tended to be healthier, but such correlations are confounded by lifestyle, since people who eat breakfast may also exercise more and smoke less.",
   "Controlled trials in adults have generally failed to show that breakfast in itself aids weight control.",
   "Context still matters. For schoolchildren, a nutritious morning meal appears to support attention and learning, particularly among those who might otherwise go hungry. For adults, the emphasis has shifted from whether to eat to what to eat. A breakfast built on protein, fiber and whole grains sustains energy, whereas refined, sugary options tend to trigger a spike in blood sugar followed by a mid-morning slump."],
  [w("maxim","noun","/ˈmæk.sɪm/","格言","a short statement of a general truth or rule","an old maxim","nutritional maxims 營養格言。"),
   w("pedigree","noun","/ˈped.ə.ɡriː/","來歷、出身","the origin and history of something","the idea's pedigree","Its pedigree 它的來歷。"),
   w("popularize","verb","/ˈpɑː.pjə.lɚ.aɪz/","使普及","to make something known and liked by many","popularize science","popularize the notion 推廣這個觀念。"),
   w("equivocal","adjective","/ɪˈkwɪv.ə.kəl/","模稜兩可的","not clear; able to be understood in more than one way","an equivocal answer","more equivocal 更不明確。"),
   w("correlation","noun","/ˌkɔːr.əˈleɪ.ʃən/","相關性","a connection between two things","a strong correlation","correlations 相關性（不等於因果）。"),
   w("confound","verb","/kənˈfaʊnd/","混淆（研究結果）","to make the results of a study unclear by another factor","confounded by age","be confounded by… 受…干擾。"),
   w("spike","noun","/spaɪk/","驟升","a sudden large increase","a spike in prices","a spike in blood sugar 血糖飆升。"),
   w("slump","noun","/slʌmp/","低落","a sudden fall in energy or activity","an afternoon slump","a mid-morning slump 上午中段的低潮。")],
  [gr("do a great deal to + V","大力促成…。","cereal manufacturers did a great deal to popularize the notion through advertising"),
   gr("from whether to… to what to…","從要不要…轉向要…什麼。","the emphasis has shifted from whether to eat to what to eat"),
   gr("whereas 表對比","然而、反之。","whereas refined, sugary options tend to trigger a spike in blood sugar")],
  [q("Why does the writer mention cereal manufacturers?","They helped popularize the breakfast slogan","They funded every study","They opposed breakfast"),
   q("Why are observational studies on breakfast hard to interpret?","Breakfast eaters may have other healthy habits","They used too few people","They studied only children"),
   q("For whom does breakfast seem especially helpful?","Schoolchildren, especially those who might go hungry","All adults trying to lose weight","Athletes only")]),
 L("A Laboratory Circling the Planet", "繞行地球的實驗室", [
   "Orbiting roughly 400 kilometers overhead at about 28,000 kilometers per hour, the International Space Station completes a circuit of the Earth approximately every 90 minutes. Its crew therefore witnesses around sixteen sunrises and sunsets in every 24-hour period.",
   "Assembled module by module from 1998 onward, the station has been continuously inhabited since November 2000, an unbroken human presence in space now lasting over two decades. It is also a diplomatic achievement, jointly operated by the space agencies of the United States, Russia, Europe, Japan and Canada, a partnership that has endured even when relations on the ground have been strained.",
   "Living in microgravity exacts a toll. Without the constant load of gravity, muscles atrophy and bones lose density, so astronauts follow a rigorous regime of around two hours of exercise daily.",
   "Studying such effects is central to the station's mission. Its findings in biology, medicine and materials science are informing preparations for longer voyages to the Moon and Mars. With the station due to be retired around 2030, attention is turning to commercial successors."],
  [w("circuit","noun","/ˈsɝː.kɪt/","一圈、環行","a journey around something","a circuit of the track","complete a circuit 繞完一圈。"),
   w("witness","verb","/ˈwɪt.nəs/","目睹","to see something happen","witness an accident","witnesses 第三人稱單數。"),
   w("inhabit","verb","/ɪnˈhæb.ɪt/","居住","to live in a place","Animals inhabit the forest.","be continuously inhabited 持續有人居住。"),
   w("diplomatic","adjective","/ˌdɪp.ləˈmæt̬.ɪk/","外交的","relating to relationships between countries","a diplomatic solution","a diplomatic achievement 外交成就。"),
   w("strained","adjective","/streɪnd/","緊張的","difficult and not friendly","strained relations","relations have been strained 關係緊張。"),
   w("atrophy","verb","/ˈæt.rə.fi/","萎縮","to become weaker from lack of use","Muscles atrophy without use.","muscles atrophy 肌肉萎縮。"),
   w("rigorous","adjective","/ˈrɪɡ.ɚ.əs/","嚴格的","very careful and strict","rigorous training","a rigorous regime 嚴格的作息。"),
   w("successor","noun","/səkˈses.ɚ/","後繼者","something that comes after and replaces another","the king's successor","commercial successors 商業接班者。")],
  [gr("分詞構句 Orbiting…","描述主詞在做的事。","Orbiting roughly 400 kilometers overhead at about 28,000 kilometers per hour"),
   gr("過去分詞片語 Assembled…","被動意義：被組裝起來的。","Assembled module by module from 1998 onward"),
   gr("exact a toll","造成損害。","Living in microgravity exacts a toll.")],
  [q("Why does the writer call the station a diplomatic achievement?","Several nations operate it together, even in tense times","It was built by one country","It hosts peace talks"),
   q("What happens to the body in microgravity?","Muscles weaken and bones lose density","People grow stronger","Nothing changes"),
   q("What is expected around 2030?","The station will be retired","A second station opens on Mars","Crews will double")]),
 L("Unraveling Fast Fashion", "拆解快時尚", [
   "Fast fashion has compressed the life cycle of a garment to an astonishing degree. Brands can translate a runway trend into affordable clothing on shop floors within weeks, refreshing their ranges so frequently that shoppers are encouraged to treat clothes as almost disposable. Global clothing production has climbed steeply, even as the number of times each item is worn has fallen.",
   "The environmental ledger is sobering. Cotton cultivation is notoriously thirsty, dyeing and finishing release chemicals into waterways, and polyester, the most common fiber, is derived from fossil fuels and sheds microplastics in the wash.",
   "The human costs are concentrated in the supply chain. The 2013 collapse of the Rana Plaza building in Bangladesh, which killed more than 1,100 garment workers, exposed how cost pressures can translate into dangerous conditions and poverty wages.",
   "Discarded garments often end up in landfills or are shipped abroad, where much of them is not reused. Remedies range from stricter regulation of supply chains to repair, resale and rental services. For individuals, the most effective step is arguably the least glamorous: buying less and wearing what we own for longer."],
  [w("compress","verb","/kəmˈpres/","壓縮","to make something smaller or shorter","compress a file","compressed 過去分詞。"),
   w("disposable","adjective","/dɪˈspoʊ.zə.bəl/","用完即丟的","intended to be thrown away after use","disposable cups","almost disposable 幾乎用完即丟。"),
   w("ledger","noun","/ˈledʒ.ɚ/","帳本、帳目","a record of gains and losses","the company ledger","The environmental ledger 環境帳。"),
   w("notoriously","adverb","/noʊˈtɔːr.i.əs.li/","出了名地（不好）","in a way that is famous for something bad","notoriously difficult","notoriously thirsty 出了名耗水。"),
   w("microplastic","noun","/ˈmaɪ.kroʊˌplæs.tɪk/","塑膠微粒","a very small piece of plastic","microplastics in the ocean","常用複數 microplastics。"),
   w("concentrate","verb","/ˈkɑːn.sən.treɪt/","集中","to be gathered in one place","Wealth is concentrated in cities.","are concentrated in… 集中在…。"),
   w("collapse","noun","/kəˈlæps/","倒塌","a sudden fall of a structure","a building collapse","the collapse of… …的倒塌。"),
   w("remedy","noun","/ˈrem.ə.di/","解決辦法","a way of solving a problem","a remedy for poverty","Remedies range from… 解法從…到…。")],
  [gr("so frequently that…","如此頻繁以致於…。","refreshing their ranges so frequently that shoppers are encouraged to treat clothes as almost disposable"),
   gr("even as","正當…的同時（對比）。","even as the number of times each item is worn has fallen"),
   gr("range from A to B","從 A 到 B 都有。","Remedies range from stricter regulation of supply chains to repair, resale and rental services.")],
  [q("What trend does the first paragraph describe?","More clothes produced but each worn less","Fewer clothes produced","Clothes lasting longer"),
   q("What did the Rana Plaza collapse expose?","Dangerous conditions linked to cost pressures","Problems with cotton farming","Microplastics in water"),
   q("What does the writer see as the most effective individual step?","Buying less and wearing clothes longer","Buying only polyester","Shopping online")]),
 L("Lessons From the Longest Study of Happiness", "最長幸福研究的啟示", [
   "Most research on human lives is a snapshot. The Harvard Study of Adult Development is a film. Begun in 1938, it has tracked the same men for decades, a cohort that originally included Harvard sophomores and teenagers from some of Boston's most disadvantaged neighborhoods. Psychiatrist Robert Waldinger, its fourth director, distills its findings in his TED talk.",
   "The headline lesson is strikingly unglamorous. Neither wealth nor fame, the goals many young people say they want most, predicted who would flourish in old age. What did was the quality of their relationships. Participants who were more socially connected tended to be happier, healthier and longer-lived, while loneliness proved toxic.",
   "Crucially, it is not the number of friends that counts but the warmth of the bonds. High-conflict marriages, for instance, appeared worse for health than divorce.",
   "Relationships also seem to protect the brain: people who felt they could genuinely rely on a partner in their eighties retained sharper memories for longer. Waldinger's conclusion is both reassuring and demanding. A good life is built less from achievements than from the ongoing, often unspectacular work of tending connections."],
  [w("snapshot","noun","/ˈsnæp.ʃɑːt/","快照、片段","a short look at something at one moment","a snapshot of the economy","a snapshot 一張快照（只看一時）。"),
   w("cohort","noun","/ˈkoʊ.hɔːrt/","研究群組","a group of people studied over time","a cohort of students","研究中被追蹤的一群人。"),
   w("disadvantaged","adjective","/ˌdɪs.ədˈvæn.t̬ɪdʒd/","弱勢的","poor and without opportunities","disadvantaged children","disadvantaged neighborhoods 弱勢社區。"),
   w("distill","verb","/dɪˈstɪl/","提煉、濃縮","to get the most important part of something","distill ideas into a book","distills its findings 濃縮研究成果。"),
   w("flourish","verb","/ˈflɝː.ɪʃ/","活得好、興旺","to be healthy and happy; to grow well","Children flourish with love.","who would flourish 誰會活得好。"),
   w("toxic","adjective","/ˈtɑːk.sɪk/","有毒的、有害的","poisonous or very harmful","a toxic relationship","proved toxic 證明有害。"),
   w("retain","verb","/rɪˈteɪn/","保持","to keep something","retain heat","retained sharper memories 記憶保持清晰。"),
   w("tend","verb","/tend/","照料","to take care of something","tend a garden","tending connections 經營關係。")],
  [gr("Neither… nor…","既不是…也不是…。","Neither wealth nor fame, the goals many young people say they want most, predicted who would flourish in old age."),
   gr("What did was…","What did = 真正能預測的（代動詞 did）。","What did was the quality of their relationships."),
   gr("less from A than from B","與其說來自 A，不如說來自 B。","A good life is built less from achievements than from the ongoing, often unspectacular work of tending connections.")],
  [q("Why does the writer call the study 'a film'?","It follows the same people over a long time","It was made into a movie","It uses video interviews"),
   q("What best predicted who would flourish in old age?","The quality of relationships","Wealth","Fame"),
   q("What surprising finding about marriage is mentioned?","High-conflict marriages appeared worse for health than divorce","All marriages improve health","Divorce always harms health")]),
]
